      resolve({ output: 'Command timed out. The computer may be busy.', error: true });
    }, timeout);

    pendingCommands.set(requestId, { resolve, timer });

    const msg = { type: 'agent_command', requestId, command, timeout };
    if (cwd) msg.cwd = cwd;
    agent.ws.send(JSON.stringify(msg));
  });
}

