    if (agentCode) {
      pendingAgents.delete(agentCode);
      for (const [uid, agent] of pairedAgents.entries()) {
        if (agent.code === agentCode) {
          pairedAgents.delete(uid);
          console.log(`[relay] Agent ${agentCode} disconnected from user ${uid}`);
