          const userWs = chatClients.get(uid);
          if (userWs && userWs.readyState === 1) {
            userWs.send(JSON.stringify({ type: 'agent_status', connected: false }));
          }
          break;
        }
      }
    }
  });

  ws.on('error', (err) => {
    console.error('[ws] Socket error:', err.message);
  });
});

process.on('SIGTERM', () => {
  wss.close(() => { server.close(() => process.exit(0)); });
});

server.listen(config.port, () => {
  const mode = process.env.ELECTRON_MODE ? 'desktop (Electron)' : 'web';
  console.log(`PC Pal server listening on port ${config.port} [${mode} mode]`);
});

module.exports = server;

