        if (updated[i].guide) {
          updated[i] = {
            ...updated[i],
            commandResults: {
              ...(updated[i].commandResults || {}),
              [command]: { output: '', running: true, error: false },
            },
          };
          break;
        }
      }
      return updated;
    });
    // Send to server
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'run_command', command }));
    }
  }, []);

