        <h1 id={titleId} className="pcp-guide__title">{guide.title}</h1>
        {!isSingleStep && (
          <div className="pcp-guide__step-indicator">
            <span className="pcp-guide__counter" aria-label={`Step ${currentStep + 1} of ${totalSteps}`}>
