      <div className="pcp-guide__content" ref={contentRef}>
        {isTerminalStep ? (
          <GuideTerminalStep
            step={step}
            onStuck={handleStuck}
          />
        ) : (
          <GuideStep
            step={step}
            onStuck={handleStuck}
          />
