          if (i < currentStep) mod = 'pcp-guide__dot--done';
          if (i === currentStep) mod = 'pcp-guide__dot--active';
          return <span key={i} className={`pcp-guide__dot ${mod}`} />;
        })}
      </span>
    );
  };

