    return (
      <div className="pcp-guide">
        {/* Top bar */}
        <div className="pcp-overlay-topbar">
          <button
            className="pcp-overlay-topbar__back"
            onClick={onClose}
            aria-label="Close guide and return to chat"
          >
            <span aria-hidden="true">&lsaquo;</span> Back to chat
          </button>
        </div>

