function getArtifactEntries(message) {
  const entries = [];
  if (message.guide) entries.push({ key: 'guide', type: 'guide', data: message.guide });
  if (message.findings) entries.push({ key: 'diagnostic', type: 'diagnostic', data: message.findings });
