/* ── Text formatting helpers ─────────────────────────────────── */

function renderInline(text) {
  if (!text) return null;
  const parts = text.split(/(\*\*[^*]+\*\*)/g);
  return parts.map((part, i) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      return <strong key={i} className="pcp-message__bold">{part.slice(2, -2)}</strong>;
