        {type === 'guide' && (
          <GuideViewer
            guide={data}
            onClose={onClose}
            onSendMessage={onSendMessage}
            onStepChange={() => {}}
            titleId={titleId}
            systemModifying={!!meta?.systemModifying}
            systemModifyingMatches={meta?.systemModifyingMatches || null}
          />
        )}
        {type === 'video' && (
          <VideoPlayer
            videos={data}
            onClose={onClose}
            titleId={titleId}
          />
        )}
        {type === 'diagnostic' && (
          <DiagnosticFindings
            findings={data}
            onClose={onClose}
            titleId={titleId}
          />
        )}
        {type === 'resources' && (
          <ResourcesViewer
            resources={data}
            onClose={onClose}
            titleId={titleId}
          />
        )}
        {type === 'practice' && (
          <PracticeMode
            practice={data}
            onClose={onClose}
            onSendMessage={onSendMessage}
            titleId={titleId}
          />
        )}
      </div>
    </div>
  );
}

