 *   - FeedbackModal (end-of-chat rating)
 *
 * @param {{
 *   userId: string,
 *   hasBuddy: boolean,
 *   viewingConversationId: string|null,
 *   onConversationChange: () => void,
 *   startNewChatRef: React.MutableRefObject,
 *   buddySessionTarget: string|null,
 *   onBuddySessionChange: (active:boolean) => void,
