  hasBuddy,
  viewingConversationId,
  onConversationChange,
  startNewChatRef,
  buddySessionTarget,
  onBuddySessionChange,
  navigate,
  onLogout,
  onContinueConversation,
  chatData,
  onArtifactOpen,
