            >
              Continue this conversation
            </button>
          )}
        </div>
      ) : (
        <InputArea
          onSend={sendMessage}
          onGatherResources={gatherResources}
          isTyping={isTyping}
          onPractice={handlePractice}
          onConnectComputer={() => setShowConnect(true)}
          onScreenShare={() => setShowScreenShare(true)}
          agentConnected={agentConnected}
