      {showScreenShare && (
        <div className="pcp-chat-screen__overlay">
          <ScreenShare
            onScreenFrame={sendScreenFrame}
            onStop={() => setShowScreenShare(false)}
          />
          <button
            type="button"
            className="pcp-chat-screen__overlay-close"
            onClick={() => setShowScreenShare(false)}
            aria-label="Close screen share"
          >
            &#10005;
          </button>
        </div>
      )}
    </div>
  );
}

