  const activeSafetyAlert = (() => {
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i].safetyAlert && !dismissedAlerts.has(messages[i].id)) {
        return messages[i].safetyAlert;
      }
    }
    return null;
  })();

