677	const createGuide = tool(
678	  'create_guide',
679	  "Create an interactive guide artifact that appears in the chat as a collapsible card with numbered steps, copy-paste terminal commands, and 'Run' buttons. Use this whenever you would give the user terminal commands — put them in a guide instead of inline text. Each step can have a description, an optional terminal command, and an optional note. The guide is rendered as a structured UI element, not text.",
680	  {
