      // pkill matches against full process name; use exact-match flag
      results.push(runFixStep('fix_kill_process_by_name', `pkill -9 -x "${name}"`));
    } else {
      results.push(runFixStep('fix_kill_process_by_name', `pkill -9 -x "${name}"`));
