      const utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = 0.85;
      utterance.onend = () => setTtsActive(false);
      utterance.onerror = () => setTtsActive(false);
      window.speechSynthesis.speak(utterance);
      setTtsActive(true);
    }
  }, [step, ttsActive]);

