    if (!systemDiagnostics.isElevated()) return adminRequiredResult('fix_reset_winsock');
    const results = [];
    results.push(runFixStep('fix_reset_winsock', 'netsh winsock reset'));
    results.push(runFixStep('fix_reset_winsock', 'netsh int ip reset'));
