  const renderDots = () => {
    if (isSingleStep) return null;
    // Truncate if >5 steps
    if (totalSteps > 5) {
      return (
        <span className="pcp-guide__dots" aria-hidden="true">
          {steps.map((_, i) => {
            if (i < currentStep) {
