            }
            if (i === currentStep) {
              return <span key={i} className="pcp-guide__dot pcp-guide__dot--active" />;
            }
            // Show first two pending, then ellipsis, then last
            if (i === currentStep + 1 || i === currentStep + 2 || i === totalSteps - 1) {
