              </span>
              {renderDots()}
            </div>
          )}
        </div>

        <div className="pcp-guide__content" ref={contentRef}>
          <GuideCompletionStep
            guide={guide}
            steps={steps}
            onDone={handleDone}
            onSendMessage={onSendMessage}
          />
        </div>
      </div>
    );
