/* ==========================================================================
   GuideViewer -- Step-by-step guide overlay (D3)
   Full-screen layout: top bar, title, scrollable step content, nav bar.
   ========================================================================== */

.pcp-guide {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--color-surface);
}

/* ── Title section ── */

.pcp-guide__title-section {
  flex-shrink: 0;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.pcp-guide__title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-1);
  line-height: var(--line-height-tight);
  margin: 0;
}

.pcp-guide__source {
  font-size: var(--font-size-xs, 0.75rem);
  color: var(--color-text-3, #6b7280);
  margin-top: var(--space-1, 4px);
}

.pcp-guide__step-indicator {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-2);
}

.pcp-guide__counter {
  font-size: var(--font-size-base);
  color: var(--color-text-2);
  font-weight: var(--font-weight-regular);
}

/* ── Progress dots ── */

.pcp-guide__dots {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.pcp-guide__dot {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-pill);
  flex-shrink: 0;
}

.pcp-guide__dot--active {
  background: var(--color-primary);
}

.pcp-guide__dot--done {
  background: var(--color-success);
}

.pcp-guide__dot--pending {
  background: transparent;
  border: 2px solid var(--color-border-strong);
}

.pcp-guide__dot-ellipsis {
  font-size: var(--font-size-xs);
  color: var(--color-text-3);
  line-height: 1;
}

/* ── Scrollable content area ── */

.pcp-guide__content {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: var(--space-4);
}

/* ── Bottom navigation ── */

.pcp-guide__nav {
  flex-shrink: 0;
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  padding-bottom: calc(var(--space-4) + var(--safe-bottom));
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.pcp-guide__nav-back {
  width: 48%;
  min-height: var(--tap-primary);
  font-size: var(--font-size-base);
}

.pcp-guide__nav-back:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.pcp-guide__nav-next {
  flex: 1;
  min-height: var(--tap-primary);
  font-size: var(--font-size-md);
}

.pcp-guide__nav-btn--full {
  width: 100%;
  min-height: var(--tap-primary);
  font-size: var(--font-size-md);
}

/* ── Step transition animation ── */

.pcp-guide__content {
  animation: pcp-guide-step-in var(--duration-base) var(--easing-decel);
}

@keyframes pcp-guide-step-in {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .pcp-guide__content {
    animation: none;
  }
}

