1	/**
2	 * PC Pal MCP Tool Server
3	 *
4	 * Exposes all PC Pal custom tools as an in-process MCP server
5	 * for use with the Claude Agent SDK. This makes the tools
6	 * provider-agnostic — any MCP-compatible agent can use them.
7	 */
8	
9	const { tool, createSdkMcpServer } = require('@anthropic-ai/claude-agent-sdk');
10	const z = require('zod');
11	
12	const { VALID_GUIDE_IDS, VOCAB_LEVELS, MEMORY_TYPES, RISK_LEVELS, FINDING_STATUSES } = require('../core/sharedConstants');
13	const FixLog = require('../models/FixLog');
14	const fsp = require('fs/promises');
15	const path = require('path');
16	const os = require('os');
17	const uiReferenceLibrary = require('../core/uiReferenceLibrary');
18	
19	// Active user context — set by the orchestrator before each query()
20	// so tools can read user_id/session_id without the model passing them
21	let _activeUserId = null;
22	let _activeSessionId = null;
23	// Active autofix session id — set only when the orchestrator is in
24	// mode 'autofix-sandbox'. Threaded into every fix_log row so each row
25	// can be traced back to a specific Sandbox tab run.
26	let _activeAutofixSessionId = null;
27	
28	function setActiveUserContext(userId, sessionId) {
29	  _activeUserId = userId;
30	  _activeSessionId = sessionId;
31	}
32	
33	function setActiveAutofixSession(sessionId) {
34	  _activeAutofixSessionId = sessionId || null;
35	}
36	
37	function getUserId() { return _activeUserId; }
38	function getSessionId() { return _activeSessionId; }
39	const systemDiagnostics = require('../core/systemDiagnostics');
40	const clientInfoStore = require('../core/clientInfoStore');
41	const youtubeSearch = require('../core/youtubeSearch');
42	const screenshotAnnotator = require('../core/screenshotAnnotator');
43	const UserMemory = require('../models/UserMemory');
44	const Anthropic = require('@anthropic-ai/sdk');
45	const { anthropicApiKey } = require('../config');
46	const skillProgression = require('../core/skillProgression');
47	const SkillEvent = require('../models/SkillEvent');
48	const SafetyEvent = require('../models/SafetyEvent');
49	const StepSequence = require('../models/StepSequence');
50	const UserNote = require('../models/UserNote');
51	const UserGoal = require('../models/UserGoal');
52	const User = require('../models/User');
53	const BuddyPair = require('../models/BuddyPair');
54	const ProgressShare = require('../models/ProgressShare');
55	const HelpRequest = require('../models/HelpRequest');
56	const SkillReview = require('../models/SkillReview');
57	const ScamCheckEvent = require('../models/ScamCheckEvent');
58	const conversationState = require('../core/conversationState');
59	const userProfileManager = require('../core/userProfileManager');
60	const supportResourceLookup = require('../core/supportResourceLookup');
61	
62	function textResult(text) {
63	  return { content: [{ type: 'text', text: String(text) }] };
64	}
65	
66	// Side-channel for structured data that Claude would otherwise consume
67	// The orchestrator reads and clears these after each query()
68	let _lastGuide = null;
69	let _lastFindings = null;
70	let _lastScreenshot = null;
71	
72	// Reference to the requestScreenshot function from index.js (set at runtime)
73	let _requestScreenshotFn = null;
74	
75	function setRequestScreenshotFn(fn) { _requestScreenshotFn = fn; }
76	
77	function getAndClearLastScreenshot() {
78	  const s = _lastScreenshot;
79	  _lastScreenshot = null;
80	  return s;
81	}
82	
83	function getAndClearLastGuide() {
84	  const g = _lastGuide;
85	  _lastGuide = null;
86	  return g;
87	}
88	
89	function getAndClearLastFindings() {
90	  const f = _lastFindings;
91	  _lastFindings = null;
92	  return f;
93	}
94	
95	/**
96	 * Check if diagnostics can actually see the user's machine.
97	 * Returns true in Electron mode (local) or if running on localhost.
98	 * Returns false on deployed web servers where diagnostics would show container data.
99	 */
100	function canRunLocalDiagnostics() {
101	  if (process.env.ELECTRON_MODE) return true;
102	  // If running on localhost (dev mode), server IS the user's machine
103	  const port = process.env.PORT || '3001';
104	  if (port === '3001') return true; // dev default
105	  return false; // deployed (HF Spaces, etc.) — diagnostics show container, not user
106	}
107	
108	function noAccessMessage(toolName) {
109	  return `Cannot run ${toolName} — this would show server data, not the user's computer. ` +
110	    'Ask the user to click "Connect Computer" to connect their machine, or ask them to describe their setup.';
111	}
112	
113	// System Diagnostic Tools
114	
115	const getSystemInfo = tool(
116	  'get_system_info',
117	  "Get detailed info about the user's computer: OS version, CPU, RAM usage, disk space, uptime. Use to diagnose performance issues.",
118	  {},
119	  async () => {
120	    // In Electron/desktop mode, server diagnostics ARE the user's machine
121	    if (process.env.ELECTRON_MODE) {
122	      return textResult(systemDiagnostics.getSystemInfo());
123	    }
124	
125	    // In web mode, use browser-collected system info if available
126	    const userId = getUserId();
127	    const browserInfo = userId ? clientInfoStore.get(userId) : null;
128	    if (browserInfo) {
129	      return textResult(clientInfoStore.formatBrowserSystemInfo(browserInfo));
130	    }
131	
132	    // No relay agent and no browser info — cannot see the user's computer
133	    return textResult(
134	      'IMPORTANT: I cannot see this user\'s actual computer. No relay agent is connected and browser detection was not available. ' +
135	      'DO NOT guess or make up system specs. Tell the user you need them to connect their computer using the Connect Computer button, ' +
136	      'or ask them to describe their device manually.'
137	    );
138	  }
139	);
140	
141	const checkNetwork = tool(
142	  'check_network',
143	  "Check internet connection, Wi-Fi status, DNS resolution, and network latency. Use when user reports internet or Wi-Fi problems.",
144	  {},
145	  async () => {
146	    if (!canRunLocalDiagnostics()) return textResult(noAccessMessage('network check'));
147	    return textResult(systemDiagnostics.checkNetwork());
148	  }
149	);
150	
151	const listRunningApps = tool(
152	  'list_running_apps',
153	  "List running applications and their resource usage (CPU/memory). Use to find apps slowing down the computer.",
154	  {},
155	  async () => {
156	    if (!canRunLocalDiagnostics()) return textResult(noAccessMessage('app listing'));
157	    return textResult(systemDiagnostics.listRunningApps());
158	  }
159	);
160	
161	const readErrorLog = tool(
162	  'read_error_log',
163	  "Read recent system error logs to diagnose crashes, freezes, or other problems.",
164	  { source: z.enum(['system', 'application', 'crash']).optional().describe('Which log: system, application, or crash') },
165	  async (args) => {
166	    if (!canRunLocalDiagnostics()) return textResult(noAccessMessage('error log'));
167	    return textResult(systemDiagnostics.readErrorLog(args.source));
168	  }
169	);
170	
171	const runSafeCommand = tool(
172	  'run_safe_command',
173	  "Run a safe, read-only diagnostic command. Only allowlisted commands work. NEVER use for destructive operations.",
174	  {
175	    command: z.string().describe('The diagnostic command to run'),
176	    reason: z.string().describe('Why you are running this command'),
177	  },
178	  async (args) => {
179	    if (!canRunLocalDiagnostics()) return textResult(noAccessMessage('terminal command'));
180	    console.log(`[MCP] Safe command: "${args.command}" — ${args.reason}`);
181	    return textResult(systemDiagnostics.runSafeCommand(args.command));
182	  }
183	);
184	
185	const checkDiskHealth = tool(
186	  'check_disk_health',
187	  "Check disk space usage, large folders, and temp files. Use when user says computer is full or running out of space.",
188	  {},
189	  async () => {
190	    if (!canRunLocalDiagnostics()) return textResult(noAccessMessage('disk check'));
191	    return textResult(systemDiagnostics.checkDiskHealth());
192	  }
193	);
