1	import React, { useState, useRef, useCallback } from 'react';
2	import GuideViewer from '../Artifacts/GuideViewer/GuideViewer';
3	import VideoPlayer from '../Artifacts/VideoPlayer';
4	import DiagnosticFindings from '../Artifacts/DiagnosticFindings';
5	import ResourcesViewer from '../Artifacts/ResourcesViewer';
6	import PracticeMode from '../Artifacts/PracticeMode/PracticeMode';
7	import './ArtifactPanel.css';
8	
9	/**
10	 * ArtifactPanel -- Desktop-only right panel, resizable via drag handle.
11	 * Only rendered when an artifact is open (ShellLayout gates this).
12	 */
13	function ArtifactPanel({ artifact, onClose, onSendMessage, onMoveInline }) {
14	  const titleId = 'pcp-artifact-panel-title';
15	  const panelRef = useRef(null);
16	  const [width, setWidth] = useState(480);
17	  const dragging = useRef(false);
18	
19	  const handleMouseDown = useCallback((e) => {
20	    e.preventDefault();
21	    dragging.current = true;
22	    const startX = e.clientX;
23	    const startW = width;
24	
25	    const onMove = (ev) => {
26	      if (!dragging.current) return;
27	      const delta = startX - ev.clientX;
28	      const newW = Math.max(320, Math.min(800, startW + delta));
29	      setWidth(newW);
30	      // Update CSS grid column in real time
31	      const shell = panelRef.current?.closest('.pcp-shell');
32	      if (shell) shell.style.setProperty('--artifact-w-live', newW + 'px');
33	    };
34	    const onUp = () => {
35	      dragging.current = false;
36	      document.removeEventListener('mousemove', onMove);
37	      document.removeEventListener('mouseup', onUp);
38	    };
39	    document.addEventListener('mousemove', onMove);
40	    document.addEventListener('mouseup', onUp);
41	  }, [width]);
42	
43	  if (!artifact) return null;
44	
45	  const renderContent = () => {
46	    switch (artifact.type) {
47	      case 'guide':
48	        return (
49	          <GuideViewer
50	            guide={artifact.data}
51	            onClose={onClose}
52	            onSendMessage={onSendMessage}
53	            onStepChange={() => {}}
54	            titleId={titleId}
55	          />
56	        );
57	      case 'video':
58	        return (
59	          <VideoPlayer
60	            videos={artifact.data}
61	            onClose={onClose}
62	            titleId={titleId}
63	          />
64	        );
65	      case 'diagnostic':
66	        return (
67	          <DiagnosticFindings
68	            findings={artifact.data}
69	            onClose={onClose}
70	            titleId={titleId}
71	          />
72	        );
73	      case 'resources':
74	        return (
75	          <ResourcesViewer
76	            resources={artifact.data}
77	            onClose={onClose}
78	            titleId={titleId}
79	          />
80	        );
81	      case 'practice':
82	        return (
83	          <PracticeMode
84	            practice={artifact.data}
85	            onClose={onClose}
86	            onSendMessage={onSendMessage}
87	            titleId={titleId}
88	          />
89	        );
90	      default:
91	        return null;
92	    }
93	  };
94	
95	  return (
96	    <aside
97	      className="pcp-artifact-panel"
98	      aria-label="Artifact viewer"
99	      aria-labelledby={titleId}
100	      ref={panelRef}
101	      style={{ width: width + 'px' }}
102	    >
103	      {/* Drag handle on left edge */}
104	      <div
105	        className="pcp-artifact-panel__resize"
106	        onMouseDown={handleMouseDown}
107	        role="separator"
108	        aria-orientation="vertical"
109	        aria-label="Resize artifact panel"
