const { VALID_GUIDE_IDS, buildComfortGuidelines, VOCAB_LEVELS, RISK_LEVELS } = require('./sharedConstants');
const { resolveModel, DEFAULT_MODEL } = require('./modelProvider');
const ollamaClient = require('./ollamaClient');
const screenshotAnnotator = require('./screenshotAnnotator');
const { lookupDll, formatDllDiagnosis } = require('./dllLookup');
const { loadCoachingNotes, filterResponse, cleanResponseMarkers, trackQuality } = require('./orchestratorShared');
const { detectSystemModifying, flattenGuideText } = require('./systemModifyingDetector');

// Injected from server/index.js — captures screenshot from relay agent or browser screen share
let _requestScreenshotFn = null;
function setRequestScreenshotFn(fn) { _requestScreenshotFn = fn; }

if (!anthropicApiKey) {
  console.warn('[agentOrchestrator] ANTHROPIC_API_KEY is not set — AI calls will fail. Running in degraded mode.');
}

const client = new Anthropic({ apiKey: anthropicApiKey });

const FALLBACK_RESPONSE =
  "I'm having a little trouble right now. Could you try asking me again in a moment?";
const MAX_TOOL_ROUNDS = 10;

// getAndClearLastScreenshot is imported from pcpalTools.js (line 21)

const tools = [
  {
    name: 'log_skill_started',
    description: 'Log that the user has started learning a new skill. Call this when you begin teaching a new topic.',
    input_schema: {
      type: 'object',
      properties: {
        skill_name: { type: 'string', description: 'Name of the skill being taught' },
      },
      required: ['skill_name'],
    },
  },
  {
    name: 'flag_emergency',
    description: 'Flag a potential emergency. Use this if the user expresses distress, mentions falling, injury, or medical concerns.',
    input_schema: {
      type: 'object',
      properties: {
        reason: { type: 'string', description: 'Why this was flagged as an emergency' },
      },
      required: ['reason'],
    },
  },
  {
    name: 'create_guide',
    description: 'Create an interactive step-by-step guide artifact that appears in the side panel. Use this for ANY multi-step procedure (sending email, video calling, printing, etc.). Each step can include a screenshot image via image_id.',
    input_schema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Guide title, e.g. "How to Send an Email in Gmail"' },
        description: { type: 'string', description: 'Optional brief description' },
        source: { type: 'string', description: 'Optional source attribution' },
        steps: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              text: { type: 'string', description: 'Step instruction text' },
              image_id: { type: 'string', description: 'Optional image ID from the UI reference library' },
              command: { type: 'string', description: 'Optional terminal command' },
              note: { type: 'string', description: 'Optional tip or warning' },
            },
            required: ['text'],
          },
          description: 'Array of guide steps',
        },
      },
      required: ['title', 'steps'],
    },
  },
  {
    name: 'create_findings',
