        ).join('\n');
        result = `VERIFIED_RESOURCES:\n${formatted}`;
      }
    } catch (err) {
      console.error('[agentOrchestrator] lookup_support_resources error:', err.message);
      result = 'Unable to look up resources right now.';
    }
